args.script:
const page = await this.openPageDesign({ pageId: "ai-leave-request-form-observe-mq7c11wg-1" });

// 1. 创建请假申请数据表
await page.editDataSet(async (ds) => {
  ds.createTable({
    tableName: "LeaveRequest",
    columns: [
      { name: "id", type: "number", label: "ID" },
      { name: "applicant", type: "string", label: "申请人" },
      { name: "leaveType", type: "string", label: "请假类型" },
      { name: "startDate", type: "string", label: "开始日期" },
      { name: "endDate", type: "string", label: "结束日期" },
      { name: "duration", type: "number", label: "请假天数" },
      { name: "reason", type: "string", label: "请假原因" },
      { name: "status", type: "string", label: "审批状态" }
    ]
  });
});

// 2. 构建页面节点树：表单区 + 列表区
await page.editNodeTree(async (tree) => {
  // 根容器
  tree.addNode({
    parentComponentId: null,
    node: { type: "r-page", id: "root", props: {}, children: [] }
  });

  // 页面标题
  tree.addNode({
    parentComponentId: "root",
    node: { type: "r-title", id: "page-title", props: { text: "请假申请" } }
  });

  // 表单区容器
  tree.addNode({
    parentComponentId: "root",
    node: {
      type: "r-form",
      id: "leave-form",
      props: {
        dataViewKey: "LeaveRequest@default",
        dataMember: "currentRow"
      },
      children: []
    }
  });

  // 申请人
  tree.addNode({
    parentComponentId: "leave-form",
    node: { type: "r-input", id: "f-applicant", props: { field: "applicant", label: "申请人", placeholder: "请输入申请人姓名" } }
  });

  // 请假类型
  tree.addNode({
    parentComponentId: "leave-form",
    node: { type: "r-select", id: "f-leaveType", props: { field: "leaveType", label: "请假类型", options: [{ label: "事假", value: "事假" }, { label: "病假", value: "病假" }, { label: "年假", value: "年假" }, { label: "调休", value: "调休" }, { label: "婚假", value: "婚假" }, { label: "产假", value: "产假" }] } }
  });

  // 开始日期
  tree.addNode({
    parentComponentId: "leave-form",
    node: { type: "r-date-picker", id: "f-startDate", props: { field: "startDate", label: "开始日期" } }
  });

  // 结束日期
  tree.addNode({
    parentComponentId: "leave-form",
    node: { type: "r-date-picker", id: "f-endDate", props: { field: "endDate", label: "结束日期" } }
  });

  // 请假天数
  tree.addNode({
    parentComponentId: "leave-form",
    node: { type: "r-input-number", id: "f-duration", props: { field: "duration", label: "请假天数", min: 0.5, step: 0.5 } }
  });

  // 请假原因
  tree.addNode({
    parentComponentId: "leave-form",
    node: { type: "r-textarea", id: "f-reason", props: { field: "reason", label: "请假原因", placeholder: "请输入请假原因" } }
  });

  // 提交按钮（append-row 闭环）
  tree.addNode({
    parentComponentId: "leave-form",
    node: { type: "r-button", id: "btn-submit", props: { text: "提交申请", action: "append-row", dataViewKey: "LeaveRequest@default" } }
  });

  // 列表区标题
  tree.addNode({
    parentComponentId: "root",
    node: { type: "r-title", id: "list-title", props: { text: "请假记录" } }
  });

  // 列表区
  tree.addNode({
    parentComponentId: "root",
    node: {
      type: "r-table",
      id: "leave-list",
      props: {
        dataViewKey: "LeaveRequest@default",
        dataMember: "rows"
      },
      children: []
    }
  });

  // 列表列定义
  const listColumns = [
    { id: "col-applicant", props: { field: "applicant", label: "申请人" } },
    { id: "col-leaveType", props: { field: "leaveType", label: "请假类型" } },
    { id: "col-startDate", props: { field: "startDate", label: "开始日期" } },
    { id: "col-endDate", props: { field: "endDate", label: "结束日期" } },
    { id: "col-duration", props: { field: "duration", label: "请假天数" } },
    { id: "col-reason", props: { field: "reason", label: "请假原因" } },
    { id: "col-status", props: { field: "status", label: "审批状态" } }
  ];
  for (const col of listColumns) {
    tree.addNode({
      parentComponentId: "leave-list",
      node: { type: "r-table-column", id: col.id, props: col.props }
    });
  }
});

// 3. 写入 script.js 与 style.css
page.setFileText("script.js", "// 请假申请页面脚本\n// 表单提交由 append-row 闭环处理，如需自定义提交逻辑可在此扩展\n");
page.setFileText("style.css", "/* 请假申请页面样式 */\n");

// 4. 返回四文件结果
return {
  ruleJson: page.getFileText("rule.json"),
  pageDataJson: page.getFileText("pagedata.json"),
  script: page.getFileText("script.js"),
  style: page.getFileText("style.css")
};

